export function rulesKey(portal,user){if(!portal||!user)throw Error('Sign in before saving attributes.');return 'reg.attribute.rules.v1:'+JSON.stringify([portal,user]);}
export function saveRules(storage,key,selections){const prior=JSON.parse(storage.getItem(key)||'{}');for(const item of selections){const url=new URL(item.url);if(url.protocol!=='https:'||url.search||url.hash||url.username||url.password||!Array.isArray(item.fields)||!item.fields.every(field=>typeof field==='string'))throw Error('Invalid attribute selection.');prior[item.url]=[...new Set(item.fields)];}storage.setItem(key,JSON.stringify(prior));}
export function readRules(storage,key,url,available){const stored=JSON.parse(storage.getItem(key)||'{}')[url];if(stored===undefined)return null;if(!Array.isArray(stored)||!stored.every(field=>typeof field==='string'))throw Error('Saved attributes are invalid.');return {fields:stored.filter(field=>available.includes(field)),missing:stored.filter(field=>!available.includes(field))};}
